-- Initial schema.
-- Conventions: ids are TEXT (generated by the Worker), timestamps are INTEGER
-- unix milliseconds, booleans are INTEGER 0/1, *_json columns hold JSON text.
-- Tokens are stored only as hashes. Every domain table carries space_id so
-- every query can filter by tenant.

CREATE TABLE users (
  id                TEXT PRIMARY KEY,
  display_name      TEXT NOT NULL,
  avatar_url        TEXT,
  primary_email     TEXT,
  locale            TEXT,
  is_platform_admin INTEGER NOT NULL DEFAULT 0 CHECK (is_platform_admin IN (0, 1)),
  created_at        INTEGER NOT NULL,
  last_seen_at      INTEGER,
  deleted_at        INTEGER
);
CREATE UNIQUE INDEX users_primary_email_idx ON users (primary_email)
  WHERE primary_email IS NOT NULL AND deleted_at IS NULL;

CREATE TABLE identities (
  id               TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  provider         TEXT NOT NULL CHECK (provider IN ('discord', 'email')),
  provider_user_id TEXT NOT NULL,
  email            TEXT,
  created_at       INTEGER NOT NULL,
  UNIQUE (provider, provider_user_id)
);
CREATE INDEX identities_user_idx ON identities (user_id);

CREATE TABLE email_tokens (
  token_hash TEXT PRIMARY KEY,
  email      TEXT NOT NULL,
  purpose    TEXT NOT NULL CHECK (purpose IN ('login', 'link')),
  expires_at INTEGER NOT NULL,
  used_at    INTEGER
);
CREATE INDEX email_tokens_email_idx ON email_tokens (email);
CREATE INDEX email_tokens_expires_idx ON email_tokens (expires_at);

CREATE TABLE sessions (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  user_agent TEXT,
  ip_hash    TEXT,
  revoked_at INTEGER
);
CREATE INDEX sessions_user_idx ON sessions (user_id);
CREATE INDEX sessions_expires_idx ON sessions (expires_at);

CREATE TABLE platform_settings (
  key        TEXT PRIMARY KEY,
  value_json TEXT NOT NULL CHECK (json_valid(value_json)),
  updated_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  updated_at INTEGER NOT NULL
);

CREATE TABLE spaces (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  slug          TEXT NOT NULL UNIQUE,
  owner_id      TEXT NOT NULL REFERENCES users (id),
  plan          TEXT NOT NULL DEFAULT 'free',
  settings_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(settings_json)),
  created_at    INTEGER NOT NULL,
  deleted_at    INTEGER
);
CREATE INDEX spaces_owner_idx ON spaces (owner_id);

CREATE TABLE space_members (
  space_id   TEXT NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  role       TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'guest')),
  -- Kept when the inviter leaves: grants they gave stay valid.
  invited_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  joined_at  INTEGER NOT NULL,
  banned_at  INTEGER,
  PRIMARY KEY (space_id, user_id)
);
CREATE INDEX space_members_user_idx ON space_members (user_id);
CREATE INDEX space_members_invited_by_idx ON space_members (space_id, invited_by);
-- Exactly one owner per space.
CREATE UNIQUE INDEX space_members_one_owner_idx ON space_members (space_id) WHERE role = 'owner';

CREATE TABLE rooms (
  id             TEXT PRIMARY KEY,
  space_id       TEXT NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  kind           TEXT NOT NULL CHECK (kind IN ('fixed', 'quick')),
  name           TEXT NOT NULL,
  slug           TEXT NOT NULL,
  visibility     TEXT NOT NULL DEFAULT 'space' CHECK (visibility IN ('space', 'restricted')),
  settings_json  TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(settings_json)),
  created_by     TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at     INTEGER NOT NULL,
  last_active_at INTEGER,
  expires_at     INTEGER,
  archived_at    INTEGER,
  UNIQUE (space_id, slug),
  -- Quick rooms always expire; fixed rooms never do.
  CHECK ((kind = 'quick') = (expires_at IS NOT NULL))
);
CREATE INDEX rooms_space_idx ON rooms (space_id, archived_at);
CREATE INDEX rooms_expires_idx ON rooms (expires_at) WHERE expires_at IS NOT NULL;

CREATE TABLE room_access (
  room_id    TEXT NOT NULL REFERENCES rooms (id) ON DELETE CASCADE,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  can_view   INTEGER NOT NULL DEFAULT 1 CHECK (can_view IN (0, 1)),
  can_stream INTEGER NOT NULL DEFAULT 0 CHECK (can_stream IN (0, 1)),
  granted_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  granted_at INTEGER NOT NULL,
  expires_at INTEGER,
  PRIMARY KEY (room_id, user_id)
);
CREATE INDEX room_access_user_idx ON room_access (user_id);

CREATE TABLE invites (
  id                TEXT PRIMARY KEY,
  space_id          TEXT NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  room_id           TEXT REFERENCES rooms (id) ON DELETE CASCADE,
  token_hash        TEXT NOT NULL UNIQUE,
  role              TEXT NOT NULL CHECK (role IN ('member', 'guest')),
  can_stream        INTEGER NOT NULL DEFAULT 0 CHECK (can_stream IN (0, 1)),
  requires_approval INTEGER NOT NULL DEFAULT 0 CHECK (requires_approval IN (0, 1)),
  max_uses          INTEGER NOT NULL DEFAULT 1 CHECK (max_uses >= 1),
  uses              INTEGER NOT NULL DEFAULT 0 CHECK (uses >= 0 AND uses <= max_uses),
  expires_at        INTEGER NOT NULL,
  created_by        TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at        INTEGER NOT NULL,
  revoked_at        INTEGER,
  -- A room invite makes the person a guest of that room only.
  CHECK (room_id IS NULL OR role = 'guest')
);
CREATE INDEX invites_space_idx ON invites (space_id, revoked_at);
CREATE INDEX invites_room_idx ON invites (room_id) WHERE room_id IS NOT NULL;
CREATE INDEX invites_expires_idx ON invites (expires_at);

CREATE TABLE join_requests (
  id         TEXT PRIMARY KEY,
  space_id   TEXT NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  room_id    TEXT REFERENCES rooms (id) ON DELETE CASCADE,
  user_id    TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  invite_id  TEXT REFERENCES invites (id) ON DELETE SET NULL,
  status     TEXT NOT NULL DEFAULT 'pending'
               CHECK (status IN ('pending', 'approved', 'rejected', 'cancelled', 'expired')),
  decided_by TEXT REFERENCES users (id) ON DELETE SET NULL,
  created_at INTEGER NOT NULL,
  decided_at INTEGER,
  CHECK ((status = 'pending') = (decided_at IS NULL))
);
CREATE INDEX join_requests_space_status_idx ON join_requests (space_id, status);
CREATE INDEX join_requests_user_idx ON join_requests (user_id);
-- At most one pending request per person and target.
CREATE UNIQUE INDEX join_requests_one_pending_idx
  ON join_requests (space_id, user_id, coalesce(room_id, '')) WHERE status = 'pending';

CREATE TABLE devices (
  id             TEXT PRIMARY KEY,
  user_id        TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name           TEXT NOT NULL,
  os             TEXT NOT NULL CHECK (os IN ('linux', 'windows', 'macos')),
  arch           TEXT NOT NULL,
  helper_version TEXT NOT NULL,
  token_hash     TEXT NOT NULL UNIQUE,
  created_at     INTEGER NOT NULL,
  last_seen_at   INTEGER,
  revoked_at     INTEGER
);
CREATE INDEX devices_user_idx ON devices (user_id);

CREATE TABLE audit_log (
  id         TEXT PRIMARY KEY,
  -- NULL for platform-level actions (settings, space suspension).
  space_id   TEXT REFERENCES spaces (id) ON DELETE CASCADE,
  actor_id   TEXT REFERENCES users (id) ON DELETE SET NULL,
  action     TEXT NOT NULL,
  target     TEXT,
  data_json  TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(data_json)),
  created_at INTEGER NOT NULL
);
CREATE INDEX audit_log_space_created_idx ON audit_log (space_id, created_at);

CREATE TABLE usage_daily (
  space_id       TEXT NOT NULL REFERENCES spaces (id) ON DELETE CASCADE,
  -- UTC day as 'YYYY-MM-DD'.
  day            TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  egress_gb_est  REAL NOT NULL DEFAULT 0 CHECK (egress_gb_est >= 0),
  viewer_minutes INTEGER NOT NULL DEFAULT 0 CHECK (viewer_minutes >= 0),
  stream_minutes INTEGER NOT NULL DEFAULT 0 CHECK (stream_minutes >= 0),
  PRIMARY KEY (space_id, day)
);
CREATE INDEX usage_daily_day_idx ON usage_daily (day);
